import fs from 'node:fs';
import assert from 'node:assert/strict';
const runtime=fs.readFileSync('astra-lote8-visual-controls-runtime.js','utf8');
const css=fs.readFileSync('styles.css','utf8');
const html=fs.readFileSync('dist/index.html','utf8');
const csp=JSON.parse(fs.readFileSync('dist/csp-manifest.json','utf8'));
const app=fs.readFileSync('app.js','utf8');
assert.equal(csp.scriptHashes.length,19,'CSP script count must remain stable');
assert(html.includes('TradingResearchAstraLote8'),'Lote 8 must be in hashed bundle');
assert(!html.includes('src="astra-lote8-visual-controls-runtime.js"'),'Lote 8 cannot add external runtime request');
assert(runtime.includes('originalToggle.apply(this,args)'),'Original weekday state/filter action must execute');
assert(runtime.includes('group.append(button)'),'Must move existing buttons, never replace with different state');
assert(runtime.includes("aria-pressed"),'Segmented controls must announce multi-selection state');
assert(runtime.includes("focus({preventScroll:true})"),'Keyboard focus must survive redraw');
assert(!/state\.(operations|tradingPlans)\s*=|saveState\(|persist\(/.test(runtime),'No data mutations/persistence in Lote 8');
assert(css.includes('--tr8-info-circle')&&css.includes('min-inline-size:28px'),'Info visual and hit sizes separated');
assert(css.includes('tr8-week-selector')&&css.includes('grid-template-columns:repeat(7'),'Uniform 7-day segments');
assert(app.includes('ui.filters.days.includes(i)')&&app.includes("data-tr-action-click=\"tpBuilderToggleDay\""),'Original weekday filtering intact');
console.log('Astra Lote 8 bundle PASS: CSP 19 hashes, original filters, focus, info target and responsive visual tokens');
